package glitch

import data.glitch_lib

# Define suspicious keywords related to CWE-546
suspicious_keywords := {"TODO", "FIXME", "HACK", "BUG", "LATER", "LATER2", "TEMPORARY", "WORKAROUND", "INSECURE", "VULNERABLE", "BYPASS", "TRUST", "DANGER", "CHECK", "LEAK", "HARD-CODED", "DEFAULT", "IGNORE", "FAILSAFE", "OVERRIDE"}

# Helper to check if a comment content contains suspicious keywords
contains_suspicious_keyword(comment) {
    lower_comment := lower(comment.content)
    keyword := suspicious_keywords[_]
    contains(lower_comment, lower(keyword))
}

# Rule to detect suspicious comments in UnitBlocks
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    comment := parent.comments[_]
    contains_suspicious_keyword(comment)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious comment detected (CWE-546) - Comment indicates deferred security actions or insecure defaults."
    }
}
